def _parse_until(raw: str | None) -> datetime | None:
    value = (raw or "").strip()
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed


def searching_is_active(user: dict | None) -> bool:
    if not user:
        return False
    if normalize_plan(user.get("plan")) != "searching":
        return False
    until = _parse_until(user.get("searching_until"))
    return until is not None and until > datetime.now(timezone.utc)


def searching_until_after_purchase(user: dict | None, *, days: int = SEARCHING_DAYS) -> str:
    now = datetime.now(timezone.utc).replace(microsecond=0)
    existing = _parse_until(user.get("searching_until") if user else None)
    start = existing if existing and existing > now else now
    return (start + timedelta(days=days)).isoformat()


